using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle;

internal sealed class MersenneDifferenceZeroSubsetsDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Circle/MersenneDifferenceZeroSubsets.";

    public DocumentDefinition Create()
    {
        Formula k = V("k"), a = V("a"), A = V("A");
        Formula labels = Call("Fin", k), subsets = Call("Finset", labels);
        Formula seed = Sub(Pow(Num(2), a), Num(1));
        Formula source = Call("actualSource", k, seed);
        Formula zero = Eq(Call("sum", A, source), Num(0));
        Formula rho = Pow(Call("finRotate", k), a);
        Formula fixedSubset = Eq(Call("image", A, rho), A);
        Formula positiveLength = Lt(Num(0), k);
        Formula count = Eq(Call("card", Call("Z", k, a)), Pow(Num(2), Call("gcd", a, k)));

        return DocumentDefinition.Create(ScribeNode.Create(
            "For every positive length and every natural exponent, exact integer-zero physical subsets of the Mersenne-difference source are precisely the rotation-fixed subsets, and their number is 2^gcd(a,k).",
            H("Mersenne-difference zero subsets: rotation invariance and the full count"),
            Blocks(
                Paragraph(Text("Let k be any positive natural number and a any natural number. Keep every physical label in Fin(k), put N=2^k-1, t=2^a-1 and rho=(finRotate k)^a. The source s(i)=SourceWidth.actualSource(k,t,i) is the integer centered representative of 2^i*t modulo N. Distinct physical labels remain distinct when their source values agree. Define Z(k,a) to be all Finset(Fin(k)) whose literal integer source sum is zero; it includes both endpoint subsets. There is no unit or minimal-period assumption.")),
                Paragraph(Text("The specific binary potential is f(i)=2^i. The accepted one-step power congruence includes the wrap at the full period; induction extends it to every a. Both powers are between 1 and 2^(k-1), so f(rho i)-f(i) lies in the inclusive centered interval. Centered uniqueness identifies s(i) literally with this difference. The length-one case reduces directly modulo one. This binary-power identity is the new intermediate fact; ZeroSumSubsets.source_cycle already provides the generic unsigned-potential coboundary for arbitrary seeds and is not new here.")),
                Describe.Lean(DescribeId.Create("actual-zero-iff-rotation"),
                    DeclarationHandle.Create(Prefix + "actual_zero_iff_rotation"),
                    H("Literal integer zero is physical rotation invariance"),
                    StatementSource.FromAuthor(Disp(Q(Imp(positiveLength, IffOf(zero, fixedSubset)),
                        ("k", Nat()), ("a", Nat()), ("A", subsets)))),
                    AssessedProvenance.FromRepo(),
                    Blocks(
                        Paragraph(Text("For every physical subset A, reindexing by the injective permutation gives sum_A s = mask(rho(A))-mask(A). Binary-mask injectivity then proves that this literal integer sum vanishes if and only if rho(A)=A. It is not merely a modular-zero test.")),
                        Paragraph(Text("Dynamically, the cyclic subgroup generated by rho acts on the full physical label set. The classified subsets are exactly the unions of its orbits: membership is constant along each rho-orbit. The familiar orbit picture explains the fixed-subset law, while the implemented count below uses the shared arithmetic mask bijection rather than a new orbit-enumeration framework."))),
                    DescribeRole.Theorem),
                Describe.Lean(DescribeId.Create("actual-zero-subsets-card"),
                    DeclarationHandle.Create(Prefix + "actual_zero_subsets_card"),
                    H("The complete physical zero fibre has 2^gcd(a,k) subsets"),
                    StatementSource.FromAuthor(Disp(Q(Imp(positiveLength, count),
                        ("k", Nat()), ("a", Nat())))),
                    AssessedProvenance.FromRepo(),
                    Blocks(
                        Paragraph(Text("Put d=gcd(t,2^k-1) and Q=(2^k-1)/d. The accepted zero_mask_dvd and quotient_dvd give exact zero implies Q divides mask(A). Conversely this divisibility gives the rotation-mask congruence. Empty and full have exact zero. For other subsets both masks are strictly below N, so the congruence forces equal natural masks, and the classification forces exact zero. Neither endpoint mask, 0 or N, is discarded.")),
                        Paragraph(Text("The finite mask-counting bijection is extracted once into private ZeroSumSubsets.divisible_mask_card and consumed by both the existing TwoBitZeroSubsets plus-seed count and this minus-seed count. It maps a divisible mask to mask(A)/Q in [0,d]. Multiplication by Q recovers the mask; mask_surjective provides the inverse for every Q*n. Thus there are d+1 subsets. Mathlib's unconditional Nat.pow_sub_one_gcd_pow_sub_one gives d=2^gcd(a,k)-1, hence exactly 2^gcd(a,k). The accepted plus-seed public types and their separate exact-zero bridge are preserved.")),
                        Paragraph(Text("The domain includes a=0, k=1, a>=k, a divisible by k, empty/full subsets, nonunit seeds and repeated source values at different labels. When a=0 the source is zero, rho is the identity and all 2^k subsets are counted; when k=1 both physical subsets are counted for every a. When k divides a, rho is again the identity. No extra endpoint premise or restriction 0<a<k is imposed.")),
                        Paragraph(Text("This result concerns the Mersenne-difference seed family on full physical labels. It supplies neither a general nonunit-source classification nor an ordering/capacity theorem for the full Circle problem. The group-action interpretation and standard gcd identity carry their stated library attribution; no literature novelty, independent review, official delivery or full-Circle completion is claimed."))),
                    DescribeRole.Theorem)), []));
    }

    private static Formula V(string name) => F.Id(name);
    private static Formula Name(string name) => new Formula.NamedConstant(FormulaIdentifier.Create(name));
    private static Formula Nat() => Name("Nat");
    private static Formula Num(long n) => new Formula.Number(n);
    private static Formula Call(string name, params Formula[] arguments) =>
        new Formula.FunctionCall(FormulaIdentifier.Create(name), [.. arguments]);
    private static Formula Q(Formula body, params (string Name, Formula Domain)[] variables)
    {
        for (var i = variables.Length - 1; i >= 0; i--)
            body = new Formula.Bind(FormulaQuantifier.ForAll,
                FormulaIdentifier.Create(variables[i].Name), variables[i].Domain, body);
        return body;
    }
    private static Formula Eq(Formula x, Formula y) => new Formula.Relation(x, FormulaRelationOperator.Equal, y);
    private static Formula Lt(Formula x, Formula y) => new Formula.Relation(x, FormulaRelationOperator.LessThan, y);
    private static Formula Imp(Formula x, Formula y) => new Formula.Logic(x, FormulaLogicOperator.Implies, y);
    private static Formula IffOf(Formula x, Formula y) => new Formula.Logic(x, FormulaLogicOperator.Iff, y);
    private static Formula Sub(Formula x, Formula y) => new Formula.Binary(x, FormulaBinaryOperator.Subtract, y);
    private static Formula Pow(Formula x, Formula y) => new Formula.Power(x, y);
}
